c.Put(1, "a"); c.Put(2, "b");
c.TryGet(1, out _);                       // a read is a use: 1 is now most recent
c.Put(3, "c");                            // full: evict the LRU, which is 2
T.True("2 evicted, not the key just read", !c.TryGet(2, out _));
T.True("1 survived", c.TryGet(1, out var v) && v == "a");
c.Put(1, "a2");
T.Eq("an update does not grow the cache", c.Count, 2);
T.Throws<ArgumentOutOfRangeException>("capacity 0 rejected", () => new LruCache<int, int>(0));

var clk = new ManualClock();
var c = new LruTtlCache<int, int>(3, clk);
c.Put(1, 10, 100);
clk.NowMs = 99;  T.True("alive one tick before", c.TryGet(1, out _));
clk.NowMs = 100; T.True("dead exactly at the TTL", !c.TryGet(1, out _));
T.Eq("the dead entry was removed", c.Count, 0);
clk.NowMs = 0;
var d = new LruTtlCache<int, int>(2, clk);
d.Put(1, 1, 10); d.Put(2, 2, 1000); d.TryGet(1, out _);
clk.NowMs = 20; d.Put(3, 3, 1000);        // full: 1 is expired, 2 is live
T.True("expired entry evicted before a live one", d.TryGet(2, out _));

var c = new SyncLruTtlCache<int, int>(64, new ManualClock());
Exception err = null;
Parallel.For(0, 8, t => {
    try {
        for (int i = 0; i < 20_000; i++) {
            int k = (i * 7 + t) % 200;
            if (i % 3 == 0) c.Put(k, k, 1_000_000); else c.TryGet(k, out _);
        }
    } catch (Exception e) { err = e; }
});
T.True("no exception under 8 threads", err == null);
T.True("never above capacity", c.Count <= 64);
bool torn = false;
for (int k = 0; k < 200; k++) if (c.TryGet(k, out var v) && v != k) torn = true;
T.True("no torn values", !torn);
